(412,199,$mw$FAEC7C51FC288A52F780766D243D109EEC0BD3BE452D37AE83BC060C6A88C300$mw$,$mw$cf1388d79a96340f931651cc3f2b2421$mw$,$mw$$mw$,$mw${"Id":199,"StageId":1,"CategoryId":33,"Points":10,"TitleAr":"ثمن القلم 11 وحدات. كم ثمن 8 أقلام؟","TitleEn":"Each pen costs 11 units. What do 8 pens cost?","QuestionTextAr":"ثمن القلم 11 وحدات. كم ثمن 8 أقلام؟","QuestionTextEn":"Each pen costs 11 units. What do 8 pens cost?","DetailedSolutionAr":"القانون المستخدم: السعر الكلي = ثمن القلم الواحد × عدد الأقلام. في المسألة 8 أقلام، وسعر الواحد 11 وحدة. بالتعويض: 8 × 11 = 8 × (10 + 1) = 80 + 8 = 88 وحدة نقدية.","DetailedSolutionEn":"Rule used: Total cost = price per pen × number of pens. With 8 pens at 11 units each: 8 × 11 = 8 × (10 + 1) = 80 + 8 = 88 units.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":785,"Order":1,"LatexCode":"88","IsCorrect":true},{"Id":786,"Order":2,"LatexCode":"89","IsCorrect":false},{"Id":787,"Order":3,"LatexCode":"91","IsCorrect":false},{"Id":788,"Order":4,"LatexCode":"86","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"جميع الأقلام لها السعر نفسه.","En":"Each pen has the same price."},{"Ar":"استخدم الضرب لتكرار سعر القلم بعدد الأقلام.","En":"Use multiplication to repeat the unit price for the number of pens."}],"Title":{"Ar":"حساب التكلفة الكلية","En":"Calculating total cost"},"Points":10,"Options":[{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"88"},{"Reason":{"Ar":"89 لا تساوي تكلفة 8 أقلام بسعر 11 لكل قلم.","En":"89 is not the cost of 8 pens at 11 per pen."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"89"},{"Reason":{"Ar":"91 لا تساوي تكلفة 8 أقلام بسعر 11 لكل قلم.","En":"91 is not the cost of 8 pens at 11 per pen."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"91"},{"Reason":{"Ar":"86 لا تساوي تكلفة 8 أقلام بسعر 11 لكل قلم.","En":"86 is not the cost of 8 pens at 11 per pen."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"86"}],"StageId":1,"Question":{"Ar":"ثمن القلم 11 وحدة نقدية. كم ثمن 8 أقلام؟","En":"Each pen costs 11 currency units. What is the total cost of 8 pens?"},"Solution":{"Idea":{"Ar":"التكلفة الكلية تساوي سعر الوحدة مضروباً في الكمية.","En":"Total cost equals unit price times quantity."},"Unit":{"Ar":"وحدة نقدية","En":"currency units"},"Steps":[{"Ar":"$p=11,\\quad q=8$","En":"$p=11,\\quad q=8$"},{"Ar":"$C=11\\cdot8=88$","En":"$C=11\\cdot8=88$"}],"Result":{"Ar":"$88$","En":"$88$"},"CommonError":{"Ar":"جمع السعر والكمية لا يعطي التكلفة.","En":"Adding price and quantity does not give total cost."},"FormulaLatex":"C=pq","Substitution":{"Ar":"$C=11\\times8=88$","En":"$C=11\\times8=88$"},"Verification":{"Ar":"$88\\div8=11$","En":"$88\\div8=11$"}},"TrackIds":[4],"CategoryId":33,"PrimarySkillId":6,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"جميع الأقلام لها السعر نفسه.","En":"Each pen has the same price."},{"Ar":"استخدم الضرب لتكرار سعر القلم بعدد الأقلام.","En":"Use multiplication to repeat the unit price for the number of pens."}],"Solution":{"Idea":{"Ar":"التكلفة الكلية تساوي سعر الوحدة مضروباً في الكمية.","En":"Total cost equals unit price times quantity."},"Unit":{"Ar":"وحدة نقدية","En":"currency units"},"Steps":[{"Ar":"$p=11,\\quad q=8$","En":"$p=11,\\quad q=8$"},{"Ar":"$C=11\\cdot8=88$","En":"$C=11\\cdot8=88$"}],"Result":{"Ar":"$88$","En":"$88$"},"CommonError":{"Ar":"جمع السعر والكمية لا يعطي التكلفة.","En":"Adding price and quantity does not give total cost."},"FormulaLatex":"C=pq","Substitution":{"Ar":"$C=11\\times8=88$","En":"$C=11\\times8=88$"},"Verification":{"Ar":"$88\\div8=11$","En":"$88\\div8=11$"}},"Distractors":[{"ErrorType":"","Reason":null,"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"89 لا تساوي تكلفة 8 أقلام بسعر 11 لكل قلم.","En":"89 is not the cost of 8 pens at 11 per pen."},"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"91 لا تساوي تكلفة 8 أقلام بسعر 11 لكل قلم.","En":"91 is not the cost of 8 pens at 11 per pen."},"Orde