(459,248,$mw$ABDFD8BB893A6A2885735CFA9DD7FFA7A3F99D0C010F7455E7E05A6F767CBC13$mw$,$mw$9aa88dadb5958f2fe780eac7db0234e5$mw$,$mw$$mw$,$mw${"Id":248,"StageId":2,"CategoryId":6,"Points":10,"TitleAr":"لتكن \\(f(x)=5x+8\\)، إذا كانت \\(f(x)=38\\) فأوجد x.","TitleEn":"Given \\(f(x)=5x+8\\), solve f(x)=38.","QuestionTextAr":"لتكن \\(f(x)=5x+8\\)، إذا كانت \\(f(x)=38\\) فأوجد x.","QuestionTextEn":"Given \\(f(x)=5x+8\\), solve f(x)=38.","DetailedSolutionAr":"المبدأ المستخدم: حل f(س) = 38 يعني إيجاد المدخل الذي يجعل الدالة تساوي 38. لدينا f(س) = 5س + 8؛ نحل 5س + 8 = 38. نطرح 8: 5س = 30، ثم نقسم على 5: س = 30 ÷ 5 = 6. التحقق: 5 × 6 + 8 = 38.","DetailedSolutionEn":"Rule used: Solving f(x) = 38 finds the input producing that output. With f(x) = 5x + 8, set 5x + 8 = 38. Subtract 8: 5x = 30, then divide by 5: x = 30 ÷ 5 = 6. Check: 5 × 6 + 8 = 38.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":981,"Order":1,"LatexCode":"9","IsCorrect":false},{"Id":982,"Order":2,"LatexCode":"4","IsCorrect":false},{"Id":983,"Order":3,"LatexCode":"6","IsCorrect":true},{"Id":984,"Order":4,"LatexCode":"7","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"حوّل قيمة الدالة المعطاة إلى معادلة.","En":"Turn the given function value into an equation."},{"Ar":"أزل الحد الثابت ثم اقسم الطرفين على المعامل.","En":"Remove the constant and divide both sides by the coefficient."}],"Title":{"Ar":"إيجاد مدخل دالة خطية","En":"Finding a linear function input"},"Points":10,"Options":[{"Reason":{"Ar":"الدالة عند 9 تعطي 53 لا 38.","En":"The function at 9 gives 53, not 38."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"9"},{"Reason":{"Ar":"الدالة عند 4 تعطي 28 لا 38.","En":"The function at 4 gives 28, not 38."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"4"},{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"6"},{"Reason":{"Ar":"الدالة عند 7 تعطي 43 لا 38.","En":"The function at 7 gives 43, not 38."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"7"}],"StageId":2,"Question":{"Ar":"لتكن \\(f(x)=5x+8\\)، إذا كانت \\(f(x)=38\\) فأوجد x.","En":"Given \\(f(x)=5x+8\\), solve f(x)=38."},"Solution":{"Idea":{"Ar":"لإيجاد المدخل من المخرج نحل المعادلة الخطية الناتجة عن مساواة الدالة بالقيمة المعطاة.","En":"To find the input from an output, solve the linear equation obtained by equating the function with the given value."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"$5x+8=38$","En":"$5x+8=38$"},{"Ar":"$5x=30$","En":"$5x=30$"},{"Ar":"$x=6$","En":"$x=6$"}],"Result":{"Ar":"$6$","En":"$6$"},"CommonError":{"Ar":"لا تخلط المدخل المجهول بالمخرج المعطى.","En":"Do not confuse the unknown input with the given output."},"FormulaLatex":"ax+b=y\\Rightarrow x=\\frac{y-b}{a}\\quad(a\\ne0)","Substitution":{"Ar":"$x=\\frac{38-8}{5}=6$","En":"$x=\\frac{38-8}{5}=6$"},"Verification":{"Ar":"$5\\times6+8=38$","En":"$5\\times6+8=38$"}},"TrackIds":[9],"CategoryId":6,"PrimarySkillId":28,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"حوّل قيمة الدالة المعطاة إلى معادلة.","En":"Turn the given function value into an equation."},{"Ar":"أزل الحد الثابت ثم اقسم الطرفين على المعامل.","En":"Remove the constant and divide both sides by the coefficient."}],"Solution":{"Idea":{"Ar":"لإيجاد المدخل من المخرج نحل المعادلة الخطية الناتجة عن مساواة الدالة بالقيمة المعطاة.","En":"To find the input from an output, solve the linear equation obtained by equating the function with the given value."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"$5x+8=38$","En":"$5x+8=38$"},{"Ar":"$5x=30$","En":"$5x=30$"},{"Ar":"$x=6$","En":"$x=6$"}],"Result":{"Ar":"$6$","En":"$6$"},"CommonError":{"Ar":"لا تخلط المدخل المجهول بالمخرج المعطى.","En":"Do not confuse the unknown input with the given output."},"FormulaLatex":"ax+b=y\\Rightarrow x=\\frac{y-b}{a}\\quad(a\\ne0)","Substitution":{"Ar":"$x=\\frac{38-8}{5}=6$","En":"$x=\\frac{38-8}{5}=6$"},"Verification":{"Ar":"$5\\times6+8=38$","En":"$5\\times6+8=38$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"الدالة عند 9 تعطي 53 لا 38.","En":"The function at 9 gives 53, not 38."},"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"الدالة عند 4 تعطي 28 لا 38.","En":"The function at 4 gives 28, not 38."},"Order":2},{"ErrorType":"","Reason":null,"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"الدالة عند 7 تعطي 43 لا 38.","En":"The function at 7 gives 43, not 38."},"Order":4}]}$mw$,$mw$لإيجاد المدخل من المخرج نحل المعادلة الخطية الناتجة عن مساواة الدالة بالقيمة المعطاة.

