lity."},"Unit":{"Ar":"عدد","En":"Count"},"Steps":[{"Ar":"$56+5n\\ge75$","En":"$56+5n\\ge75$"},{"Ar":"$5n\\ge19$","En":"$5n\\ge19$"},{"Ar":"$n\\ge3.8\\Rightarrow n_{\\min}=4$","En":"$n\\ge3.8\\Rightarrow n_{\\min}=4$"}],"Result":{"Ar":"$4$","En":"$4$"},"CommonError":{"Ar":"التقريب للأسفل قد لا يحقق الحد الأدنى.","En":"Rounding down may fail to reach the minimum."},"FormulaLatex":"56+5n\\ge75","Substitution":{"Ar":"$5n\\ge19\\Rightarrow n\\ge3.8\\Rightarrow n_{\\min}=4$","En":"$5n\\ge19\\Rightarrow n\\ge3.8\\Rightarrow n_{\\min}=4$"},"Verification":{"Ar":"$56+5(3)=71<75\\le76=56+5(4)$","En":"$56+5(3)=71<75\\le76=56+5(4)$"}},"Distractors":[{"ErrorType":"","Reason":null,"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"ثلاث إجابات تمنحه 71 نقطة فقط.","En":"Three answers yield only 71 points."},"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"خمس إجابات تكفي لكنها ليست الحد الأدنى.","En":"Five answers suffice but are not minimal."},"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"ست إجابات تكفي لكنها ليست الحد الأدنى.","En":"Six answers suffice but are not minimal."},"Order":4}]}$mw$,$mw$الحد الأدنى للنقاط يعطي متباينة أكبر من أو يساوي.

